/**
 * Self-check for the dsh-sandbox-allowlist package.
 *
 * Run inside the dsh installation context so `@deepseek-ai/*` resolves to the
 * installed packages. On this machine:
 *
 *   node --experimental-loader ./.dsh-test-resolve-hook.mjs test.mjs
 *
 * (the resolve-hook is generated by the dsh tooling; see README "验证").
 * Without the hook the @deepseek-ai imports fail to resolve — the pattern
 * checks can still be run standalone by commenting the plugin imports.
 */

import assert from 'node:assert/strict'
import { existsSync, mkdtempSync, mkdirSync, statSync, writeFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

import {
  hasMeta,
  patternToRegExp,
  expandTrustedRoots,
} from '../lib/patterns.mjs'
import {
  normalizeCommand,
  patternToCommandRegExp,
  compileCommandRules,
  resolveCommandAction,
  validateCommandRule,
} from '../lib/command-rules.mjs'
import {
  decideCommand,
  dispositionForAction,
  denyReason,
} from '../lib/command-gate.mjs'
import {
  describeStatement,
} from '../lib/command-rules.mjs'
import { decide, makeScopePredicate, canonicalCommandKey } from '../lib/command-decision.mjs'
import { classifyStatement, capabilityTables } from '../lib/command-classes.mjs'
import { analyzeCommand } from '../lib/command-analyze.mjs'
import { makeScriptExpander, scriptNameOf } from '../lib/command-expand.mjs'
import {
  CommandAudit,
  ProposalStore,
  SessionDecisionCache,
  describeProposal,
  explainDecision,
} from '../lib/command-audit.mjs'
import {
  NO_READ_ACTIONS,
  NO_READ_TOOLS,
  validateNoReadRule,
  compileNoReadRules,
  noReadRuleIssues,
  resolveNoRead,
} from '../lib/read-deny.mjs'
import {
  stripDaclSddl,
  revokeWriteAces,
  collectRevokeDirs,
  resolvePowerShell,
} from '../lib/acl-revoke.mjs'
import {
  MANIFEST_FILE_NAME,
  manifestPath,
  loadManifest,
  saveManifest,
  workspaceGrants,
  setWorkspaceGrants,
  diffGranted,
} from '../lib/grant-manifest.mjs'
import AllowlistPolicyService, { SETTINGS_NAMESPACE, AllowlistSettingsSchema, CommandRuleSchema, CommandSettingsSchema } from '../lib/policy.mjs'
import AllowlistFileSystem from '../lib/fs.mjs'
import AllowlistSandboxProvider from '../lib/provider.mjs'
import { SandboxPolicyService } from '@deepseek-ai/dsh-sandbox-policy'
import { SandboxedFileSystem } from '@deepseek-ai/dsh-fs-sandbox'
import { LocalSandboxProvider } from '@deepseek-ai/dsh-sandbox-local'

// ── pattern matcher ────────────────────────────────────────────────────────
assert.equal(hasMeta('D:\\Shared\\Tools'), false)
assert.equal(hasMeta('D:\\Data\\logs\\*'), true)
assert.equal(hasMeta('D:\\**\\cache'), true)

const reDoubleStar = patternToRegExp('D:\\Shared\\**')
assert.ok(reDoubleStar.test('D:\\Shared\\a'))
assert.ok(reDoubleStar.test('D:\\Shared\\a\\b\\c'))
assert.ok(!reDoubleStar.test('D:\\SharedOther\\a'))

const reSingleStar = patternToRegExp('D:\\Data\\logs\\*')
assert.ok(reSingleStar.test('D:\\Data\\logs\\x'))
assert.ok(!reSingleStar.test('D:\\Data\\logs\\x\\y'))

// ── command rules ──────────────────────────────────────────────────────────
// normalizing collapses surrounding and inner whitespace; ignores casing on win32
assert.equal(normalizeCommand('  git   status  '), 'git status')
assert.equal(normalizeCommand(''), '')
assert.equal(normalizeCommand(null), '')

// wildcard translation: `*` any run, `?` one char, anchored
const gitAny = patternToCommandRegExp('git *')
assert.ok(gitAny.test('git status --porcelain'))
assert.ok(gitAny.test('git commit -m hi'))
assert.ok(!gitAny.test('git'))
const gitCommit = patternToCommandRegExp('git commit *')
assert.ok(gitCommit.test('git commit -m hi'))
assert.ok(!gitCommit.test('git status'))
assert.ok(patternToCommandRegExp('git statu?').test('git status'))

// last-match-wins with tool-aware rules
const rules = [
  { tool: 'bash', pattern: 'git *', action: 'allow' },
  { tool: 'pwsh', pattern: 'git *', action: 'ask' },
  { pattern: 'rm -rf *', action: 'deny' }, // tool omitted ⇒ all tools
  { tool: 'bash', pattern: 'git push *', action: 'deny' }, // more specific, later
]
const match = compileCommandRules(rules)
assert.equal(match('bash', 'git status'), 'allow')
assert.equal(match('pwsh', 'git status'), 'ask')
assert.equal(match('bash', 'git push origin main'), 'deny') // last match wins
assert.equal(match('bash', 'rm -rf /tmp/x'), 'deny')        // tool-omitted applies to bash
assert.equal(match('pwsh', 'rm -rf /tmp/x'), 'deny')        // and to pwsh
assert.equal(match('bash', 'npm test'), null)               // no match

// resolveCommandAction applies the configured fallback (delegate keeps behavior)
assert.equal(resolveCommandAction(rules, 'bash', 'npm test', 'delegate'), 'delegate')
assert.equal(resolveCommandAction(rules, 'bash', 'npm test', 'ask'), 'ask')
assert.equal(resolveCommandAction([], 'bash', 'npm test', 'delegate'), 'delegate')

// malformed rules are skipped, never thrown
assert.equal(validateCommandRule({ pattern: 'git *', action: 'allow' }), null)
assert.ok(validateCommandRule({ pattern: 'git *', action: 'bogus' }) !== null)
assert.ok(validateCommandRule({ pattern: '' }) !== null)
assert.ok(validateCommandRule({ tool: 'cmd', pattern: 'x', action: 'allow' }) !== null)
assert.ok(validateCommandRule({ pattern: 'git *', action: 'allow-escalate' }) !== null, 'allow-escalate was removed: it is no longer a valid action')
assert.ok(validateCommandRule({ program: 'git', action: 'allow' }) !== null, 'the argv-level program selector was removed')

// gate decision → PreToolDecision-shaped result, with delegate sentinel
assert.equal(decideCommand({ rules, default: 'delegate' }, 'bash', 'npm test'), 'delegate')
assert.deepEqual(decideCommand({ rules }, 'bash', 'git status'), { kind: 'allow' })
assert.deepEqual(decideCommand({ rules }, 'bash', 'git push origin main'), { kind: 'deny' })
assert.deepEqual(decideCommand({ rules, default: 'ask' }, 'bash', 'npm test'), { kind: 'ask' })
assert.deepEqual(decideCommand({ rules }, 'bash', 'GIT STATUS'), { kind: 'allow' }) // win32 case-insensitive
assert.equal(dispositionForAction('allow').kind, 'allow')
assert.equal(dispositionForAction('deny').kind, 'deny')
assert.equal(dispositionForAction('ask').kind, 'ask')
assert.equal(dispositionForAction('bogus'), 'delegate')
assert.match(denyReason('bash', 'rm -rf /'), /deny rule/)

// command rule / settings schemas validate and reject junk
{
  const ruleResult = CommandRuleSchema['~standard'].validate({ pattern: 'git *', action: 'allow' })
  assert.ok('value' in ruleResult, 'command rule validates: ' + JSON.stringify(ruleResult.issues))
  assert.equal(ruleResult.value.pattern, 'git *')
  const toolResult = CommandRuleSchema['~standard'].validate({ tool: 'bash', pattern: 'git *', action: 'allow' })
  assert.ok('value' in toolResult, 'rule with tool validates')
  const badAction = CommandRuleSchema['~standard'].validate({ pattern: 'git *', action: 'go' })
  assert.ok('issues' in badAction, 'rule rejects an unknown action')
  const badTool = CommandRuleSchema['~standard'].validate({ tool: 'cmd', pattern: 'x', action: 'allow' })
  assert.ok('issues' in badTool, 'rule rejects an unknown tool')

  const cmds = CommandSettingsSchema['~standard'].validate({ default: 'ask', rules: [{ pattern: 'git *', action: 'allow' }] })
  assert.ok('value' in cmds, 'commands settings validates')
  assert.equal(cmds.value.default, 'ask')
  assert.equal(cmds.value.rules.length, 1)
}

// ── ACL reclamation (SDDL strip is pure; spawn helpers stay platform-safe) ──
  {
    // explicit + inherited copies of the workspace SID are dropped in one pass
    const sddl = 'D:AI(A;OICI;0x110156;;;S-1-4-1-2)(A;OICIID;0x110156;;;S-1-4-1-2)(A;ID;FA;;;BA)'
    const out = stripDaclSddl(sddl, 'S-1-4-1-2')
    assert.equal(out.count, 2)
    assert.equal(out.sddl, 'D:AI(A;ID;FA;;;BA)')

    // absent SID → untouched, zero count
    const untouched = stripDaclSddl('D:(A;ID;FA;;;SY)', 'S-1-4-9-9')
    assert.equal(untouched.count, 0)
    assert.equal(untouched.sddl, 'D:(A;ID;FA;;;SY)')

    // every segment naming the SID is removed, others preserved in order
    const multiple = stripDaclSddl('D:(A;OICI;0x110156;;;S-1-4-7-8)(A;ID;0x1301bf;;;AU)(A;OICI;0x110156;;;S-1-4-7-8)', 'S-1-4-7-8')
    assert.equal(multiple.count, 2)
    assert.equal(multiple.sddl, 'D:(A;ID;0x1301bf;;;AU)')

    // an empty/short DACL round-trips unchanged
    assert.equal(stripDaclSddl('D:', 'S-1-4-1-1').sddl, 'D:')

    // non-Windows invocation is a no-op; on Windows it spawns — never touched here
    const noop = revokeWriteAces([], 'S-1-4-1-2')
    assert.equal(noop.ok, true)

    // PowerShell host resolution: a host must resolve on win32, none elsewhere
    const host = resolvePowerShell()
    if (process.platform === 'win32') {
      assert.ok(host && host.exe, 'a PowerShell host resolves on win32')
      assert.equal(typeof host.pin51, 'boolean')
    } else {
      assert.equal(host, null)
    }
  }

  // ── grants manifest ───────────────────────────────────────────────────────
  {
    const manifestBase = mkdtempSync(join(tmpdir(), 'dsh-grants-man-'))
    try {
      // missing file → empty; corrupt file → empty, never throws
      const missing = manifestPath(manifestBase)
      assert.deepEqual(loadManifest(missing), { workspaces: {} })
      writeFileSync(missing, '{oops', 'utf8')
      assert.deepEqual(loadManifest(missing), { workspaces: {} })

      // round-trip: save → load → per-workspace get/set
      const manifest = { workspaces: {} }
      setWorkspaceGrants(manifest, 'W:\\work', ['D:\\Shared\\Tools', 'D:\\Data\\logs'])
      saveManifest(missing, manifest)
      const loaded = loadManifest(missing)
      assert.deepEqual(workspaceGrants(loaded, 'W:\\work'), ['D:\\Shared\\Tools', 'D:\\Data\\logs'])
      assert.deepEqual(workspaceGrants(loaded, 'W:\\other'), [])
      assert.equal(loaded.workspaces['W:\\work'].length, 2)
      assert.equal(MANIFEST_FILE_NAME, 'sandbox-allowlist-grants.json')
    } finally {
      rmSync(manifestBase, { recursive: true, force: true })
    }
  }

  // ── granted × wanted diff ─────────────────────────────────────────────────
  {
    const plain = diffGranted(['a', 'b'], ['b', 'c'])
    assert.deepEqual(plain.toAdd, ['c'])
    assert.deepEqual(plain.toRemove, ['a'])

    // parents are reclaimed before children (a child must never re-inherit
    // from a batch root that is being reclaimed in the same run)
    const nested = diffGranted(['D:\\x\\b', 'D:\\x'], [])
    assert.deepEqual(nested.toRemove, ['D:\\x', 'D:\\x\\b'])

    // duplicate wanted roots collapse
    assert.deepEqual(diffGranted([], ['a', 'a']).toAdd, ['a'])

    // identical sets → no work
    const same = diffGranted(['a', 'b'], ['b', 'a'])
    assert.deepEqual(same.toAdd, [])
    assert.deepEqual(same.toRemove, [])
  }

  // ── revoke dir collection (parents first, symlinks never followed) ────────
  {
    const treeBase = mkdtempSync(join(tmpdir(), 'dsh-revoke-tree-'))
    try {
      const root = join(treeBase, 'root')
      mkdirSync(join(root, 'a', 'deep'), { recursive: true })
      writeFileSync(join(root, 'a', 'file.txt'), 'x')
      const { dirs, missing } = collectRevokeDirs([root, join(treeBase, 'gone')])
      assert.deepEqual(missing, [join(treeBase, 'gone')])
      assert.deepEqual(dirs, [root, join(root, 'a'), join(root, 'a', 'deep')])
      assert.ok(!dirs.some((dir) => dir.endsWith('file.txt')), 'files are never collected')
    } finally {
      rmSync(treeBase, { recursive: true, force: true })
    }
  }

  // ── filesystem expansion ───────────────────────────────────────────────────
const base = mkdtempSync(join(tmpdir(), 'dsh-allowlist-test-'))
try {
  const shared = join(base, 'Shared')
  const sharedA = join(shared, 'a')
  const sharedB = join(shared, 'b')
  const deep = join(sharedB, 'c')
  for (const dir of [shared, sharedA, sharedB, deep]) mkdirSync(dir, { recursive: true })
  writeFileSync(join(sharedA, 'file.txt'), 'x')

  // literal path → the directory itself
  assert.ok(new Set(expandTrustedRoots(shared)).has(shared))

  // trailing `**` → the root itself plus every existing descendant
  const tree = new Set(expandTrustedRoots(join(shared, '**')))
  assert.ok(tree.has(shared), '** includes the anchor root')
  assert.ok(tree.has(sharedA) && tree.has(sharedB) && tree.has(deep), '** includes descendants')

  // single `*` → immediate children only, never the parent
  const children = new Set(expandTrustedRoots(join(shared, '*')))
  assert.ok(children.has(sharedA) && children.has(sharedB), '* includes immediate children')
  assert.ok(!children.has(deep), '* excludes grandchildren')
  assert.ok(!children.has(shared), '* excludes the parent')

  // missing literal → empty, never an error
  assert.deepEqual(expandTrustedRoots(join(base, 'Nope')), [])

  // missing prefix with meta → empty WITHOUT walking the drive (the prefix
  // does not exist, so no path can match)
  assert.deepEqual(expandTrustedRoots(join(base, 'NoSuch', '*')), [])
  assert.deepEqual(expandTrustedRoots(join(base, 'NoSuch', '**')), [])

  // malformed / unsafe patterns → throw with an actionable message
  assert.throws(() => expandTrustedRoots('relative/path'), /must be absolute/)
  assert.throws(() => expandTrustedRoots('D:\\**\\cache'), /anchored too broadly/)

  // ── noRead read-restriction rules ───────────────────────────────────────
  assert.deepEqual(NO_READ_ACTIONS, ['deny', 'ask'], 'no allow action by design')
  assert.deepEqual(NO_READ_TOOLS, ['read', 'read_image', 'edit'])
  assert.ok(validateNoReadRule(null) !== null)
  assert.ok(validateNoReadRule({ pattern: '', action: 'deny' }) !== null, 'empty pattern rejected')
  assert.ok(validateNoReadRule({ pattern: '*.pem', action: 'allow' }) !== null, 'allow action is rejected on purpose')
  assert.ok(validateNoReadRule({ pattern: '*.pem', action: 'bogus' }) !== null)
  assert.equal(validateNoReadRule({ pattern: '*.pem', action: 'deny' }), null)
  assert.equal(validateNoReadRule({ pattern: '.env' }), null, 'action defaults to deny')

  const rules = compileNoReadRules([
    { pattern: '*.pem', action: 'deny' },
    { pattern: '.env*', action: 'deny' },
    { pattern: 'id_rsa', action: 'deny' },
    { pattern: '**/vault/**', action: 'deny' }, // contains a separator ⇒ full-path rule
    { pattern: '*.crt', action: 'ask' },
  ])
  assert.equal(rules.length, 5)
  const hit = (target) => resolveNoRead(rules, target)

  // basename rules match the file name at any depth
  assert.equal(hit('D:\\a\\b.pem').action, 'deny', 'basename rule hits nested files')
  assert.equal(hit('secret.pem').pattern, '*.pem')
  assert.equal(hit('nested/deep/archive.pem').action, 'deny')
  assert.equal(hit('.env').pattern, '.env*', '".env*" also matches ".env" itself (zero-length tail)')
  assert.equal(hit('D:\\x\\.env.local').pattern, '.env*')
  assert.equal(hit('env.local'), null, 'not a dotfile prefix match')
  assert.equal(hit('D:\\users\\me\\.ssh\\id_rsa.pub'), null, 'exact-name rule does not match id_rsa.pub')
  assert.equal(hit('config/id_rsa').pattern, 'id_rsa', 'exact-name rule matches at any depth')
  assert.equal(hit('config/my_rsa'), null, 'only the exact name matches')

  // full-path rules match against the whole path (both separators accepted)
  assert.equal(hit('D:/x/vault/a.txt').pattern, '**/vault/**')
  assert.equal(hit('D:/x/vault/deep/a.txt').action, 'deny')
  assert.equal(hit('D:/x/vaulty/a.txt'), null, 'segment boundary respected')
  assert.equal(hit('vault/a.txt'), null, 'relative path without a leading separator misses the anchored pattern')

  // case sensitivity follows the platform convention (win insensitive)
  if (process.platform === 'win32') {
    assert.equal(hit('D:\\X\\SECRET.PEM').action, 'deny', 'Windows matching is case-insensitive')
  } else {
    assert.equal(hit('secret.PEM'), null, 'POSIX matching is case-sensitive')
  }

  // deny outranks ask when several rules match one target
  const mixed = compileNoReadRules([
    { pattern: '*.pem', action: 'ask' },
    { pattern: 'secret*', action: 'deny' },
  ])
  assert.deepEqual(resolveNoRead(mixed, 'secret.pem'), { pattern: 'secret*', action: 'deny' }, 'deny beats ask')
  assert.equal(resolveNoRead(mixed, 'other.pem').action, 'ask', 'ask returned when no deny matches')

  // malformed entries are skipped defensively
  assert.equal(compileNoReadRules([{ pattern: '*.pem', action: 'allow' }, { pattern: 'x.txt' }]).length, 1)

  // directory-level rules: an absolute literal dir OR an absolute dir ending
  // in a double-star subtree deny the anchor itself AND everything beneath it;
  // a literal absolute FILE path denies exactly that path (no descendants).
  const win32 = process.platform === 'win32'
  const dirRules = compileNoReadRules([
    { pattern: win32 ? 'D:/vault/**' : '/vault/**', action: 'deny' },     // subtree form
    { pattern: win32 ? 'D:/bank' : '/bank', action: 'deny' },             // literal dir → subtree
    { pattern: win32 ? 'D:/etc-app.conf' : '/etc-app.conf', action: 'deny' }, // literal file (top level, no rule overlap)
  ])
  assert.equal(dirRules.length, 3)
  const dhit = (target) => resolveNoRead(dirRules, target)
  const p = (win) => win ? 'D:/' : '/'
  assert.equal(dhit(`${p(win32)}vault`).action, 'deny', 'subtree rule denies the anchor itself (listing)')
  assert.equal(dhit(`${p(win32)}vault/a/b.txt`).action, 'deny', 'subtree rule denies descendants')
  assert.equal(dhit(`${p(win32)}vault/key.pem`).action, 'deny', 'file under the denied vault is denied by the subtree rule')
  assert.equal(dhit(`${p(win32)}vaultx/a.txt`), null, 'dir segment boundary respected')
  assert.equal(dhit(`${p(win32)}bank`).action, 'deny', 'literal dir denies itself')
  assert.equal(dhit(`${p(win32)}bank/deep/notes.txt`).action, 'deny', 'literal dir denies descendants')
  assert.equal(dhit(`${p(win32)}bank2/x`), null)
  assert.equal(dhit(`${p(win32)}etc-app.conf`).action, 'deny', 'literal file path denies the exact path')
  assert.equal(dhit(`${p(win32)}etc-app.conf.bak`), null, 'literal file path is exact (no prefix leak)')
  if (win32) {
    assert.equal(dhit('D:/VAULT/UP.TXT').action, 'deny', 'Windows dir matching is case-insensitive')
  }

  // breadth guards refuse whole-drive/whole-fs and every-file patterns
  assert.equal(noReadRuleIssues([{ pattern: 'D:\\', action: 'deny' }]).length, 1, 'drive-root dir rule refused')
  assert.equal(noReadRuleIssues([{ pattern: '/', action: 'deny' }]).length, 1, 'fs-root dir rule refused')
  for (const wildcard of ['*', '**', '?']) {
    assert.equal(noReadRuleIssues([{ pattern: wildcard }]).length, 1, `pure wildcard "${wildcard}" refused`)
  }
  assert.equal(compileNoReadRules([{ pattern: 'D:\\', action: 'deny' }, { pattern: '*.pem' }]).length, 1, 'broad rule skipped, concrete rule kept')
  assert.equal(compileNoReadRules([{ pattern: '*', action: 'deny' }]).length, 0)

  // ── plugin classes ───────────────────────────────────────────────────────
  assert.ok(AllowlistPolicyService.prototype instanceof SandboxPolicyService)
  assert.ok(AllowlistFileSystem.prototype instanceof SandboxedFileSystem)
  assert.ok(AllowlistSandboxProvider.prototype instanceof LocalSandboxProvider)

  // Config schema: parses a full config and applies defaults
  const result = AllowlistPolicyService.Config['~standard'].validate({
    mode: 'workspace-write',
    workspaceRoot: base,
    allowedDirs: [join(shared, '**')],
    commands: { default: 'ask', rules: [{ pattern: 'git *', action: 'allow' }] },
    noRead: [{ pattern: '*.pem' }, { pattern: '**/.env', action: 'ask' }],
  })
  assert.ok('value' in result, 'config validates: ' + JSON.stringify(result.issues))
  const parsed = result.value
  assert.equal(parsed.mode, 'workspace-write')
  assert.deepEqual(parsed.allowedDirs, [join(shared, '**')])
  assert.equal(parsed.commands.rules.length, 1, 'commands config is parsed')
  assert.equal(parsed.commands.default, 'ask')
  assert.equal(parsed.strict, false, 'defaults are applied')
  assert.equal(parsed.noRead.length, 2, 'noRead config is parsed')
  assert.equal(parsed.noRead[0].action, 'deny', 'noRead rule action defaults to deny')
  assert.equal(parsed.noRead[1].action, 'ask')

  // Config schema: rejects junk
  const bad = AllowlistPolicyService.Config['~standard'].validate({ mode: 'bogus' })
  assert.ok('issues' in bad, 'bogus mode is rejected')
  const noReadBad = AllowlistPolicyService.Config['~standard'].validate({
    mode: 'workspace-write',
    workspaceRoot: base,
    noRead: [{ pattern: '*.pem', action: 'allow' }],
  })
  assert.ok('issues' in noReadBad, 'noRead "allow" action is rejected by the config schema')
  const noReadBad2 = AllowlistPolicyService.Config['~standard'].validate({
    mode: 'workspace-write',
    workspaceRoot: base,
    noRead: [{ action: 'deny' }],
  })
  assert.ok('issues' in noReadBad2, 'noRead rule without a pattern is rejected')

  // Settings namespace schema: parses and carries the warning copy
  assert.equal(SETTINGS_NAMESPACE, 'sandbox-allowlist')
  const settingsResult = AllowlistSettingsSchema['~standard'].validate({
    allowedDirs: ['D:\\Shared\\**'],
    commands: { default: 'delegate', rules: [{ pattern: 'rm -rf *', action: 'deny' }] },
    noRead: [{ pattern: '*.pem', action: 'deny' }],
  })
  assert.ok('value' in settingsResult, 'settings schema validates')
  assert.deepEqual(settingsResult.value.allowedDirs, ['D:\\Shared\\**'])
  assert.equal(settingsResult.value.commands.rules.length, 1, 'commands section validates')
  assert.equal(settingsResult.value.noRead.length, 1, 'noRead section validates')
  assert.ok('issues' in AllowlistSettingsSchema['~standard'].validate({
    noRead: [{ pattern: '*.pem', action: 'allow' }],
  }), 'settings schema rejects the "allow" action too')
  // The settings page renders schema.toJSON() — the warning must ride the wire
  const wire = JSON.stringify(AllowlistSettingsSchema.toJSON())
  assert.ok(wire.includes('安全警示'), 'settings schema carries the warning copy on the wire')
  assert.ok(wire.includes('noRead'), 'settings schema carries the noRead section on the wire')

  // ── pattern rules over per-statement descriptors ─────────────────────────
  {
    // The statement's program token is normalized before pattern matching:
    // quotes, paths and Windows launcher suffixes disappear, so `git *` also
    // matches a quoted full path to git.exe.
    const pathRules = [{ pattern: 'git *', action: 'allow' }]
    const resolvePath = compileCommandRules(pathRules)
    assert.equal(resolvePath('bash', describeStatement('git status --porcelain')), 'allow')
    assert.equal(resolvePath('bash', describeStatement('"C:\\Program Files\\Git\\git.exe" status')), 'allow', 'a quoted program path reduces to the program name')
    assert.equal(resolvePath('bash', describeStatement('git')), null, 'the bare program does not match the `git *` pattern (needs the space)')
    assert.equal(resolvePath('pwsh', describeStatement('& git status')), 'allow', 'the pwsh call operator is skipped in the normalized text')

    const narrowRules = [
      { pattern: 'git status*', action: 'allow' },
      { pattern: 'git push*', action: 'ask' },
    ]
    const resolveNarrow = compileCommandRules(narrowRules)
    assert.equal(resolveNarrow('bash', describeStatement('git status --porcelain')), 'allow')
    assert.equal(resolveNarrow('bash', describeStatement('git push origin main')), 'ask', 'last match wins within the same statement')
    assert.equal(resolveNarrow('bash', describeStatement('gitdb status')), null, 'patterns anchor at the start, so gitdb never matches git')
    const toolRules = [{ tool: 'pwsh', pattern: 'Get-Content *', action: 'ask' }]
    const resolveTool = compileCommandRules(toolRules)
    assert.equal(resolveTool('pwsh', describeStatement('Get-Content ./id.pem')), 'ask')
    assert.equal(resolveTool('bash', describeStatement('Get-Content ./id.pem')), null, 'a tool-scoped rule does not leak to the other shell')

    assert.ok(validateCommandRule({ action: 'allow' }) !== null, 'a rule without a pattern is refused')
    assert.ok(validateCommandRule({ pattern: 'git *', action: 'grant' }) !== null, 'unknown actions are refused')
  }

  // ── capability classification ─────────────────────────────────────────────
  {
    const kind = (statement, options) => classifyStatement(describeStatement(statement), options).kind
    assert.equal(kind('git status'), 'read')
    assert.equal(kind('git push origin main'), 'external')
    assert.equal(kind('git branch -D feature'), 'destructive')
    assert.equal(kind('git commit -m x'), 'local-write')
    assert.equal(kind('git log -5'), 'read')
    assert.equal(kind('cat ./notes.md'), 'read')
    assert.equal(kind('sed s/a/b/ f'), 'opaque', 'sed scripts can execute (e) and write (w/r), so sed is opaque')
    assert.equal(kind('yq .a f.yml'), 'read', 'yq reads')
    assert.equal(kind('yq -i .a f.yml'), 'local-write', 'yq -i writes in place')
    assert.equal(kind('find . -name x'), 'read')
    assert.equal(kind('find . -exec rm {} ;'), 'local-write', 'find -exec is not a read')
    assert.equal(kind('python -c "x"'), 'opaque')
    assert.equal(kind('python --version'), 'read')
    assert.equal(kind('Get-Content x'), 'read', 'approved Get verb')
    assert.equal(kind('Set-Content x y'), 'local-write')
    assert.equal(kind('Remove-Item -Recurse x'), 'destructive')
    assert.equal(kind('docker ps'), 'read', 'docker ps is a read-only form')
    assert.equal(kind('docker run x'), 'external')
    assert.equal(kind('acme-unknown --flag'), 'unknown')

    // path scope feeds local-write verdicts
    const inScope = (token) => !/^[A-Za-z]:[\\/]/.test(token)
    assert.deepEqual(classifyStatement(describeStatement('mkdir ./logs'), { inScope }).outside, [])
    assert.deepEqual(classifyStatement(describeStatement('mkdir D:/Elsewhere/logs'), { inScope }).outside, ['D:/Elsewhere/logs'])

    // A "read" that names an out-of-scope path reports it, so the escalation
    // gate can refuse it even though the program itself only reads.
    const readOutside = classifyStatement(describeStatement('cat D:/Elsewhere/x'), { inScope })
    assert.equal(readOutside.kind, 'read')
    assert.deepEqual(readOutside.outside, ['D:/Elsewhere/x'], 'a read reports out-of-scope paths')

    // Single source of truth: a program must live in exactly one table. A
    // duplicate whose tables disagree is how a "read-only" label ends up on
    // something that writes.
    {
      const tables = capabilityTables()
      const direct = {
        read: tables.read,
        'local-write': tables.localWrite,
        destructive: tables.destructive,
        opaque: tables.opaque,
        external: tables.external,
        'repo-exec': tables.repoExec,
      }
      const owner = new Map()
      for (const [kind, programs] of Object.entries(direct)) {
        for (const program of programs) {
          assert.equal(owner.get(program), undefined, `"${program}" appears twice in the direct capability tables`)
          owner.set(program, kind)
        }
      }
      // Dispatchers checked BEFORE the direct tables must own their programs
      // exclusively — if they also appear in a direct table, the two can drift.
      for (const { program } of tables.guarded) {
        assert.equal(owner.get(program), undefined, `guarded program "${program}" is also in the ${owner.get(program)} table`)
      }
      for (const program of tables.packageManagers) {
        assert.equal(owner.get(program), undefined, `package manager "${program}" is also in the ${owner.get(program)} table`)
      }
    }
  }

  // ── structural analysis (substitutions / redirects / heredocs) ────────────
  {
    const nested = analyzeCommand('echo $(echo $(whoami))', 'bash', { inScope: () => true })
    assert.deepEqual(nested.statements.map((statement) => statement.program), ['whoami', 'echo', 'echo'], 'nested substitutions are analyzed innermost-first')
    assert.equal(nested.unresolved.length, 0, 'two levels is inside the default depth budget')

    const backtick = analyzeCommand('echo `whoami`', 'bash', { inScope: () => true })
    assert.deepEqual(backtick.statements.map((statement) => statement.program), ['whoami', 'echo'], 'bash backticks are substitutions')
    const pwshBacktick = analyzeCommand('Write-Output a`;b', 'pwsh', { inScope: () => true })
    assert.equal(pwshBacktick.substitutions.length, 0, 'a pwsh backtick is an escape, never a substitution')

    const depth = analyzeCommand('echo $(echo $(echo $(whoami)))', 'bash', { inScope: () => true, maxDepth: 1 })
    assert.ok(depth.unresolved.some((item) => item.kind === 'depth-exceeded'), 'recursion overflow is unresolved (fail-closed)')

    const outOfScope = analyzeCommand('git status > D:/Elsewhere/out.txt', 'bash', {
      inScope: (token) => !token.startsWith('D:/Elsewhere'),
    })
    assert.equal(outOfScope.redirects[0].inScope, false, 'redirect targets are resolved against the scope')

    const single = analyzeCommand("echo 'no $(substitution) here'", 'bash', { inScope: () => true })
    assert.equal(single.substitutions.length, 0, 'single quotes suppress substitution')
  }

  // ── scope predicate (workspace ∪ granted roots) ───────────────────────────
  {
    const inScope = makeScopePredicate(['D:/Repo', 'D:/Shared/Tools'], 'D:/Repo')
    assert.equal(inScope('D:/Repo/src/a.ts'), true)
    assert.equal(inScope('./src/a.ts'), true, 'relative paths resolve against the cwd')
    assert.equal(inScope('D:\\Repo\\src\\a.ts'), true, 'backslashes normalize')
    assert.equal(inScope('D:/Repo2/a.ts'), false, 'a sibling with a shared prefix is NOT inside')
    assert.equal(inScope('D:/Shared/Tools/x'), true, 'granted roots count as inside')
    assert.equal(inScope('D:/Elsewhere/x'), false)
    assert.equal(inScope('../../Elsewhere/x'), false, '.. escapes are resolved before the check')
    assert.equal(inScope('~/.ssh/id_rsa'), false, 'home-relative paths leave the workspace')
    assert.equal(inScope('/etc/passwd'), false, 'a POSIX absolute path has no known mapping')
  }

  // ── meta-program expansion (package.json scripts) ─────────────────────────
  {
    const manifest = JSON.stringify({
      scripts: { test: 'vitest run', deploy: 'sh ./deploy.sh', pretest: 'node ./prep.mjs', lint: 'eslint src' },
    })
    assert.equal(scriptNameOf('pnpm', 'test', (name) => name === 'test'), 'test', 'bare subcommand resolving to a script')
    assert.equal(scriptNameOf('pnpm', 'install', () => false), null, 'a bare builtin is not a script when none is defined')
    assert.equal(scriptNameOf('npm', 'run lint', () => true), 'lint', 'explicit run subcommand')
    assert.equal(scriptNameOf('node', 'test', () => true), null, 'only package managers expand')

    const expand = makeScriptExpander({ workspaceRoot: 'D:/Repo', readFile: () => manifest, onWarn: () => {} })
    assert.match(expand('pnpm', 'test'), /node \.\/prep\.mjs/, 'pre-lifecycle hooks are folded in')
    assert.match(expand('pnpm', 'test'), /vitest run/, 'the script body is included')
    assert.equal(expand('pnpm', 'publish'), null, 'not a script')
    const broken = makeScriptExpander({ workspaceRoot: 'D:/Repo', readFile: () => { throw new Error('ENOENT') }, onWarn: () => {} })
    assert.equal(broken('pnpm', 'test'), null, 'an unreadable manifest degrades to null (fail-closed)')
  }

  // ── decision engine: aggregation and explanations ─────────────────────────
  {
    const context = { roots: ['D:/Repo'], cwd: 'D:/Repo' }
    const sandbox = (source, command, tool = 'bash') => decide({ source, tool, command, phase: 'sandbox', context })
    const denyWins = sandbox({ rules: [{ pattern: 'rm *', action: 'deny' }, { pattern: 'pnpm *', action: 'allow' }], default: 'delegate' }, 'pnpm lint; rm -rf ./x')
    assert.equal(denyWins.verdict, 'deny', 'deny outranks allow across statements')
    const askWins = sandbox({ rules: [{ pattern: 'git push*', action: 'ask' }], default: 'delegate' }, 'git status && git push')
    assert.equal(askWins.verdict, 'ask', 'ask outranks the baseline')
    const baseline = sandbox({ rules: [], default: 'delegate' }, 'git status | cat')
    assert.equal(baseline.verdict, 'allow', 'the baseline allows read-only statements with no rules')
    const noBaseline = sandbox({ rules: [], default: 'delegate', baseline: false }, 'git status | cat')
    assert.equal(noBaseline.verdict, 'delegate', 'baseline=false returns the decision to the rules')
    const delegated = sandbox({ rules: [], default: 'delegate' }, 'acme-tool run')
    assert.equal(delegated.verdict, 'delegate', 'an unknown program delegates')

    const explained = explainDecision(denyWins)
    assert.match(explained, /判定：deny/, 'explainDecision renders the verdict')
    assert.match(explained, /rm -rf \.\/x/, 'and the per-statement breakdown')

    assert.equal(canonicalCommandKey('  git   push  origin '), canonicalCommandKey('git push origin'), 'canonical key collapses whitespace and quotes')
  }

  // ── audit / session cache / proposals ─────────────────────────────────────
  {
    const audit = new CommandAudit({ cap: 2, file: join(base, 'decisions.jsonl') })
    audit.record({ phase: 'sandbox', tool: 'bash', command: 'a', verdict: 'allow' })
    audit.record({ phase: 'sandbox', tool: 'bash', command: 'b', verdict: 'ask' })
    audit.record({ phase: 'escalation', tool: 'bash', command: 'c', verdict: 'ask' })
    assert.equal(audit.recent().length, 2, 'the ring is bounded')
    assert.equal(audit.recent()[1].command, 'c', 'the newest entry is last')
    assert.ok(existsSync(join(base, 'decisions.jsonl')), 'the JSONL audit sink is written')

    // The append-only sink rotates instead of growing for the lifetime of the
    // installation (a 2 MiB default, tiny here to keep the test fast).
    const rotating = new CommandAudit({ file: join(base, 'rotate.jsonl'), maxBytes: 200, maxFiles: 2 })
    for (let i = 0; i < 12; i += 1) {
      rotating.record({ phase: 'sandbox', tool: 'bash', command: `cmd-${i}`, verdict: 'allow' })
    }
    assert.ok(existsSync(join(base, 'rotate.jsonl.1')), 'the sink rotated once it passed maxBytes')
    assert.ok(
      statSync(join(base, 'rotate.jsonl')).size <= 200 + 400,
      'the live sink is bounded (a rotation happens once per maxBytes)',
    )
    assert.ok(!existsSync(join(base, 'rotate.jsonl.3')), 'rotated files beyond maxFiles are dropped')

    const cache = new SessionDecisionCache({ cap: 2 })
    assert.equal(cache.lookup('bash', 'git  push'), null, 'nothing remembered yet')
    cache.remember('bash', 'git push', { phase: 'escalation' })
    assert.ok(cache.lookup('bash', 'git   push') !== null, 'whitespace-only variants share the canonical key')
    assert.equal(cache.lookup('bash', 'git push --force'), null, 'a changed argument is a different command')
    assert.equal(cache.lookup('pwsh', 'git push'), null, 'the tool is part of the key')
    cache.remember('bash', 'a'); cache.remember('bash', 'b'); cache.remember('bash', 'c')
    assert.equal(cache.size, 2, 'the cache is bounded (FIFO)')
    assert.equal(new SessionDecisionCache({ enabled: false }).remember('bash', 'x'), false, 'a disabled cache stores nothing')

    const proposals = new ProposalStore({ threshold: 2 })
    assert.equal(proposals.note({ tool: 'bash', program: 'cargo', rest: 'fmt', kind: 'opaque', phase: 'escalation' }), null, 'below threshold: no proposal yet')
    const proposed = proposals.note({ tool: 'bash', program: 'cargo', rest: 'fmt', kind: 'opaque', phase: 'escalation' })
    assert.equal(proposed.program, 'cargo', 'the second approval proposes a rule')
    assert.equal(proposed.action, 'allow', 'every proposal is an allow rule (it carries the escalation grant by itself)')
    assert.deepEqual(proposals.proposedRules()[0].pattern, 'cargo fmt*', 'the proposal converts to a pattern rule')
    assert.match(describeProposal(proposed), /cargo fmt\*/, 'the proposal renders readably')
  }

  console.log('dsh-sandbox-allowlist: all checks passed')
} finally {
  rmSync(base, { recursive: true, force: true })
}